#requires -Modules Hyper-V
param([string[]]$ComputerName = @('HYPERV01'))
function Get-VmHealth {
    param([string]$Name)
    $vms = Invoke-Command -ComputerName $Name -ScriptBlock { Get-VM } 
    foreach ($vm in $vms) {
        if ($vm.State -eq 'Running' -and $vm.MemoryAssigned -gt 8GB) {
            Write-Warning ("{0} on {1} is using {2:N1} GB RAM" -f $vm.Name, $Name, ($vm.MemoryAssigned/1GB))
        } else {
            Write-Output ("{0}: {1}" -f $vm.Name, $vm.State)
        }
    }
}
