    if ($user.LastLogonDate -lt (Get-Date).AddDays(-90)) {
        Write-Host "STALE: $($user.SamAccountName) last logon $($user.LastLogonDate)"
    }
    else {
        Write-Host "Disabled: $($user.SamAccountName)"
    }
}
