function Get-StaleADUser {
    <#
    .SYNOPSIS
        Lists AD users who have not logged on recently.
    .DESCRIPTION
        Finds enabled user accounts whose LastLogonDate is older than the
        cutoff. Accepts usernames from the pipeline or scans all users.
    .PARAMETER DaysInactive
        Days of inactivity that marks an account stale. Default 90.
    .PARAMETER SamAccountName
        One or more usernames. Accepts pipeline input.
    .EXAMPLE
        Get-StaleADUser -DaysInactive 60
    .EXAMPLE
        'jdoe','asmith' | Get-StaleADUser
    #>
    [CmdletBinding()]
    param(
        [int]$DaysInactive = 90,

        [Parameter(ValueFromPipeline = $true)]
        [string[]]$SamAccountName
    )

    begin {
        $cutoff = (Get-Date).AddDays(-$DaysInactive)
        Write-Verbose "Cutoff date: $cutoff"
    }

    process {
        try {
            if ($SamAccountName) {
                foreach ($name in $SamAccountName) {
                    $user = Get-ADUser -Identity $name `
                        -Properties LastLogonDate -ErrorAction Stop
                    if ($user.Enabled -and $user.LastLogonDate -lt $cutoff) {
                        $user | Select-Object SamAccountName, LastLogonDate,
                            @{Name='DaysInactive';
                              Expression={((Get-Date) - $_.LastLogonDate).Days}}
                    }
                }
            }
            else {
                Get-ADUser -Filter * -Properties LastLogonDate `
                    -ErrorAction Stop |
                    Where-Object { $_.Enabled -and
                                   $_.LastLogonDate -lt $cutoff } |
                    Select-Object SamAccountName, LastLogonDate,
                        @{Name='DaysInactive';
                          Expression={((Get-Date) - $_.LastLogonDate).Days}}
            }
        }
        catch {
            Write-Error "AD query failed: $_"
        }
    }

    end {
        Write-Verbose "Scan complete."
    }
}

